require_once __DIR__.'/customer-settings-state.php';require_once __DIR__.'/customer-mail.php';
function ocs_text(array $d,string $key,int $max,bool $required=true):string{$v=$d[$key]??'';ocs_need(is_string($v)&&mb_check_encoding($v,'UTF-8')&&!str_contains($v,"\0")&&mb_strlen($v)<=$max&&(!$required||trim($v)!==''),'Проверьте поле «'.$key.'».',422);return trim($v);}
function ocs_email(array $d,string $key):string{$v=ocs_text($d,$key,190);ocs_need((bool)filter_var($v,FILTER_VALIDATE_EMAIL)&&preg_match('/^[\x21-\x7e]+$/D',$v)===1,'Укажите корректный email без переводов строки.',422);return mb_strtolower($v);}
function ocs_status(array $s):array{$draft=isset($s['draft_policy'])?ocs_policy($s['draft_policy']):null;$p=ocs_active_policy($s);return ['ok'=>true,'version'=>$s['version'],'prep_enabled'=>($s['prep_enabled']??false)===true,'public_enabled'=>false,'portal_enabled'=>($s['portal_enabled']??$s['public_enabled']??false)===true,'policy_approved'=>(bool)$p,'policy_version'=>$p['version']??null,'policy'=>$draft??$p,'mail_verified'=>isset($s['mail_verified_at']),'mail_from'=>$s['mail']['from']??null,'pending_mail_from'=>$s['pending_mail']['from']??null,'has_password'=>isset($s['mail']['password']),'inbox_confirmation_pending'=>isset($s['probe_hash'])&&($s['probe_expires']??0)>time(),'smtp_host'=>'smtp.spaceweb.ru','smtp_port'=>465,'email_notifications_enabled'=>($s['email_notifications_enabled']??false)===true,'max_workflow_notifications_enabled'=>($s['max_workflow_notifications_enabled']??false)===true,'max_connected'=>function_exists('max_status')?(bool)max_status()['connected']:false,'owner_defaults'=>['operator_name'=>'Сухарева Наталья Владимировна','operator_address'=>'Романово, Калининградская область','contact'=>'MAX: https://max.ru/u/f9LHodD0cOKgQK_L9u-un2-ttcwfRfu_-_a-2Ai_usx_frNtjq1jjuiZSLE; Telegram: @minden2006']];}
function ocs_prepare_policy(array $d):array{
 $operator=ocs_text($d,'operator_name',190);$address=ocs_text($d,'operator_address',1000);$contact=ocs_text($d,'contact',1000);$basis=ocs_text($d,'legal_basis',5000);$retention=ocs_text($d,'retention',5000);$processors=ocs_text($d,'processors',5000);$version='customer-privacy-'.gmdate('Ymd').'-'.bin2hex(random_bytes(8));
 $policy="Политика обработки данных кабинета клиентов НейроДело\nВерсия ".$version."\n\nОператор: ".$operator.". Адрес для обращений: ".$address.". Контакт для запросов: ".$contact.".\n\nНазначение: регистрация и подтверждение email, приглашения в кабинет, подготовка и исполнение договоров, согласование заданий и результата, передача материалов и документов, учёт сообщений об оплате и проверки поступлений, предоставление официальных чеков и поддержка по согласованным условиям. Согласие кабинета не объединяется с подписанием договора и не является электронной подписью. Рекламные рассылки этим действием не разрешаются.\n\nКатегории: имя/наименование и email аккаунта; подтверждённые контакты; хеш пароля и технические сведения сессии; необходимые реквизиты стороны договора и полномочия представителя, ИНН ИП/организации; брифы, сообщения, материалы и подписанные копии; суммы, даты, назначение и плательщик по сообщению клиента, записи ручной сверки, официальные чеки, решения и история согласований. Паспортные сканы, данные банковских карт, пароли инфраструктуры и ключи доступа не запрашиваются для обычной регистрации и не должны передаваться в сообщениях или документах.\n\nОснования обработки, проверенные оператором: ".$basis."\n\nХранение, сроки и прекращение обработки: ".$retention."\n\nПривлечённые лица, сервисы и условия обработки, проверенные оператором: ".$processors.". Фактическая почтовая настройка кабинета использует SMTP SpaceWeb с TLS.\n\nДоступ: владелец и авторизованный клиент в пределах его заказов. Документы и файлы находятся вне публичного каталога, запросы проверяют роль и принадлежность. Заявление клиента об оплате не подтверждает банк. Запись владельцем чека не означает независимую проверку ФНС. MAX получает только номер события и ссылку на закрытый кабинет, без содержания брифов и документов; отправка почты означает принятие SMTP, а не доказанный просмотр получателем.\n\nЗапросы о доступе, уточнении, прекращении обработки и отзыве согласия направляются оператору по указанному контакту. Оператор рассматривает запрос с учётом применимого закона и сохраняющихся договорных/налоговых оснований; прекращение согласия не выдаётся системой за автоматическое удаление обязательных документов. Политика первичной формы заявки на сайте остаётся отдельным документом.";
 $consent="Отдельное согласие на обработку данных кабинета клиентов НейроДело\nВерсия ".$version."\n\nЯ свободно и осознанно предоставляю ".$operator." (адрес: ".$address.", контакт: ".$contact.") согласие на обработку необходимых данных кабинета для регистрации, связи по заказу, подготовки/исполнения договоров и поддержки в объёме и на условиях политики этой версии. Данные: имя и email, необходимые контакты и реквизиты договора, добровольно переданные брифы/материалы/подписанные копии, сообщения и решения, сведения о расчётах и чеках, технические сведения защиты доступа. Действия: получение, запись, систематизация, хранение, уточнение, использование для указанных целей, предоставление авторизованной стороне заказа и указанным в политике обработчикам, прекращение/удаление при отсутствии сохраняющихся законных оснований.\n\nСроки и порядок прекращения: ".$retention.". Отзыв направляется оператору по указанному контакту. Это согласие оформляется отдельно от договора, коммерческого предложения, приёмки и рекламы. Оно не подтверждает оплату и не является юридически значимой электронной подписью. Чекбокс не отмечен заранее. Фиксируются время, версия и контрольная сумма документа.";
 $p=['version'=>$version,'policy_text'=>$policy,'consent_text'=>$consent];$p['hash']=hash('sha256',json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$p['state']='NEEDS_LEGAL_REVIEW';$p['created_at']=gmdate('c');$p['prepared_by']=1;return $p;
}
function ocs_probe_mail(array &$s,array $d):void{
 $email=ocs_email($d,'from');$recipient=ocs_email($d,'recipient');$password=$d['password']??'';ocs_need(is_string($password)&&strlen($password)<=256&&!preg_match('/[\r\n\x00]/',$password),'Проверьте пароль почтового ящика.',422);if($password===''&&($s['mail']['from']??null)===$email)$password=$s['mail']['password']??'';ocs_need($password!==''&&!preg_match('/[\r\n\x00]/',$password),'Введите пароль почтового ящика в эту защищённую форму, не в чат.',422);$mail=['transport'=>'smtp','host'=>'smtp.spaceweb.ru','port'=>465,'encryption'=>'ssl','username'=>$email,'from'=>$email,'password'=>$password];$host=parse_url(config()['app_url'],PHP_URL_HOST);
 if((config()['customer_settings_test_mode']??false)===true&&in_array($host,['127.0.0.1','localhost','::1'],true)){$test=config()['customer_mail']??[];ocs_need(($test['transport']??'')==='test-smtp'&&in_array($test['host']??'',['127.0.0.1','::1'],true),'Тестовый транспорт не задан.');$mail=array_replace($mail,array_intersect_key($test,array_flip(['transport','host','port','encryption'])));}
 $code=(string)random_int(100000,999999);$body="Проверка почты кабинета НейроДело. Код: ".$code."\r\nВведите код в защищённом кабинете владельца в течение 15 минут. Это письмо не активирует клиентские аккаунты.\r\n";$message='From: '.$email."\r\nTo: ".$recipient."\r\nSubject: =?UTF-8?B?".base64_encode('Код настройки кабинета НейроДело')."?=\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n".chunk_split(base64_encode($body),76,"\r\n");
 ocs_need(customer_smtp_send($recipient,$message,$mail),'SMTP не подтвердил принятие письма. Проверьте ящик и пароль SpaceWeb; настройки не активированы.',502);$salt=bin2hex(random_bytes(16));$s['pending_mail']=$mail;$s['pending_recipient']=$recipient;$s['probe_salt']=$salt;$s['probe_hash']=hash('sha256',$salt.$code);$s['probe_expires']=time()+900;$s['probe_attempts']=0;ocs_save($s,'smtp_accepted',['inbox_confirmed'=>false]);
}
