 current_session($method!=='GET');rate('owner-customer-settings',120);if($method==='GET'&&$route==='')json_response(ocs_status(ocs_read()));ocs_need($method==='POST','Метод не разрешён.',405);$d=input();$result=ocs_locked(function()use($route,$d){$s=ocs_read();ocs_need(is_int($d['version']??null)&&$d['version']===$s['version'],'Настройки изменились. Обновите страницу и повторите решение.',409);
 if($route==='policy/draft'){$p=ocs_prepare_policy($d);ocs_policy_write($p);$s['draft_policy']=$p['version'];ocs_save($s,'privacy_draft_created',['version'=>$p['version'],'hash'=>$p['hash']]);}
 elseif($route==='policy/approve'){$p=isset($s['draft_policy'])?ocs_policy($s['draft_policy']):null;ocs_need($p&&in_array($p['state'],['NEEDS_LEGAL_REVIEW','APPROVED'],true)&&($d['hash']??'')===$p['hash']&&($d['confirm_reviewed']??false)===true,'Прочитайте и явно одобрите точную версию политики и отдельного согласия.',422);$reason=ocs_text($d,'reason',4000);ocs_need(!preg_match('/\[(?:Заполнить|Уточнить)/u',$p['policy_text'].$p['consent_text']),'В проекте остались незаполненные поля.',422);if($p['state']!=='APPROVED'){$p['state']='APPROVED';$p['approved_at']=gmdate('c');$p['approved_by']=1;$p['approval_reason']=$reason;ocs_policy_write($p);}$s['policy_version']=$p['version'];$s['policy_hash']=$p['hash'];unset($s['draft_policy']);ocs_save($s,'privacy_approved',['version'=>$p['version'],'hash'=>$p['hash']]);}
 elseif($route==='mail/probe'){rate('owner-customer-mail-probe',3);ocs_probe_mail($s,$d);}
 elseif($route==='mail/confirm'){$code=ocs_text($d,'code',6);ocs_need(isset($s['probe_hash'],$s['pending_mail'])&&($s['probe_expires']??0)>time()&&($s['probe_attempts']??0)<5,'Код истёк или превышено число попыток. Повторите тестовую отправку.',422);if(!preg_match('/^[0-9]{6}$/D',$code)||!hash_equals($s['probe_hash'],hash('sha256',$s['probe_salt'].$code))){$s['probe_attempts']++;ocs_save($s,'inbox_code_rejected');return ['ok'=>false,'code_rejected'=>true,'version'=>$s['version']];}$s['mail']=$s['pending_mail'];$s['owner_notification_email']=$s['pending_recipient'];$s['mail_verified_at']=gmdate('c');foreach(['pending_mail','pending_recipient','probe_salt','probe_hash','probe_expires','probe_attempts'] as $key)unset($s[$key]);ocs_save($s,'inbox_confirmed');}
 elseif($route==='enable-preparation'){ocs_need(ocs_active_policy($s)!==null&&($d['confirm']??false)===true,'Сначала одобрите политику кабинета и подтвердите подготовку заказов.',422);$s['prep_enabled']=true;ocs_save($s,'owner_preparation_enabled');}
 elseif($route==='notifications'){ocs_need(ocs_active_policy($s)!==null&&($d['confirm']??false)===true,'Сначала проверьте политику и подтвердите каналы уведомлений.',422);$email=($d['email_notifications_enabled']??false)===true;$max=($d['max_workflow_notifications_enabled']??false)===true;ocs_need(!$email||isset($s['mail_verified_at'],$s['owner_notification_email']),'Для email нужен подтверждённый почтовый ящик.',422);ocs_need(!$max||function_exists('max_status')&&max_status()['connected'],'MAX ещё не подключён. Подключите бота в кабинете владельца.',422);if($email||$max){$tables=db()->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('nd_crm_notifications','nd_notification_outbox')")->fetchAll(PDO::FETCH_COLUMN);ocs_need(count($tables)===2,'Сначала завершите миграции очереди уведомлений.');}$s['email_notifications_enabled']=$email;$s['max_workflow_notifications_enabled']=$max;ocs_save($s,'notification_channels_selected',['email'=>$email,'max'=>$max]);}
 elseif($route==='open'){ocs_need(ocs_active_policy($s)!==null&&isset($s['mail_verified_at'],$s['mail'])&&($s['prep_enabled']??false)===true&&($d['confirm']??false)===true,'Нужны одобренные документы, подготовка владельца и подтверждённый почтовый ящик.',422);$s['public_enabled']=false;$s['portal_enabled']=true;ocs_save($s,'paid_client_portal_opened');}
 elseif($route==='close'){ocs_need(($d['confirm']??false)===true,'Подтвердите закрытие доступа.',422);$s['public_enabled']=false;$s['portal_enabled']=false;ocs_save($s,'client_portal_closed');}else ocs_need(false,'Раздел не найден.',404);return ocs_status($s);});json_response($result);
}
